def stage(record)
  @pending[record.id] = record.attributes.slice("id", "email", "last_seen")
end

def flush!
  rows = @pending.values            # one row per id: earlier writes coalesced
  @pending.clear
  ActiveRecord::Base.transaction do
    Record.upsert_all(rows, unique_by: :id)   # single multi-row statement
  end
end
